from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
path='/root/output/result.xlsx'
wb=load_workbook(path)  # no data_only
ws=wb['Task']
print('Sheets:', wb.sheetnames)
print('No new sheets added:', wb.sheetnames == ['Task', 'Data'])
print('\nSample formulas:')
for addr in ['H12','L17','H19','L24','H26','L31','H35','L40','H42','I43','J44','K45','L46','H47','H50','L50']:
    print(f'{addr}: {ws[addr].value}')

# Targeted structural verification.
errors=[]
expected_sheets=['Task','Data']
if wb.sheetnames != expected_sheets:
    errors.append(f'sheets {wb.sheetnames} != {expected_sheets}')

for r in list(range(12,18)) + list(range(19,25)) + list(range(26,32)):
    for c in range(8,13):
        col=get_column_letter(c)
        exp=f'=INDEX(Data!$H$21:$L$38,MATCH($D{r},Data!$D$21:$D$38,0),MATCH({col}$10,Data!$H$4:$L$4,0))'
        got=ws.cell(r,c).value
        if got != exp:
            errors.append(f'{col}{r}: expected {exp}, got {got}')

for offset, r in enumerate(range(35,41)):
    cf=12+offset; op=19+offset; base=26+offset
    for c in range(8,13):
        col=get_column_letter(c)
        exp=f'=({col}{cf}-{col}{op})/{col}{base}*100'
        got=ws.cell(r,c).value
        if got != exp:
            errors.append(f'{col}{r}: expected {exp}, got {got}')

for c in range(8,13):
    col=get_column_letter(c)
    exps={
        42:f'=MIN({col}35:{col}40)',
        43:f'=MAX({col}35:{col}40)',
        44:f'=MEDIAN({col}35:{col}40)',
        45:f'=AVERAGE({col}35:{col}40)',
        46:f'=PERCENTILE({col}35:{col}40,0.25)',
        47:f'=PERCENTILE({col}35:{col}40,0.75)',
        50:f'=SUMPRODUCT({col}35:{col}40,{col}26:{col}31)/SUM({col}26:{col}31)',
    }
    for r, exp in exps.items():
        got=ws.cell(r,c).value
        if got != exp:
            errors.append(f'{col}{r}: expected {exp}, got {got}')

print('\nVerification:', 'PASS' if not errors else 'FAIL')
if errors:
    for e in errors[:50]:
        print('ERROR:', e)
    raise SystemExit(1)
